    if m=='fsutil' or m.startswith('fsutil.'):
        del sys.modules[m]
import fsutil
out={}
for name in dir(fsutil):
    if name.startswith('_'): continue
    obj=getattr(fsutil,name)
    if callable(obj) and (inspect.isfunction(obj)):
        try: out[name]=str(inspect.signature(obj))
        except Exception as e: out[name]='ERR '+str(e)
print(json.dumps(out, indent=0, sort_keys=True))
EOF
